window.STATION_PARTS=window.STATION_PARTS||{};
window.STATION_PARTS["apu"]={"id":"apu","title":"APU and powerplant","color":"#55687A","stations":[
{"id":"apu-1","subject":"apu","order":1,"kind":"lesson","level":1,"ident":"APU","title":"APU at a glance","goal":"Explicar qué es el APU, qué entrega al avión, quién lo controla y de dónde saca energía, combustible y aceite.","intro":"El APU es un pequeño motor propio del avión. Empezamos por qué da y quién lo maneja.","minutes":6,"cards":[{"id":"apu-1-c1","title":"What the APU gives","body":"El **APU** (Auxiliary Power Unit) es una unidad independiente que entrega **aire (bleed)** y **energía eléctrica**:\n- **en tierra:** aire para arrancar los motores y para el aire acondicionado, y electricidad para la red;\n- **en el despegue:** aire para el aire acondicionado, por ejemplo cuando se necesita la mejor performance;\n- **en vuelo:** respaldo de la red eléctrica y del aire acondicionado, y aire para arrancar un motor.","keyIdea":"El APU da aire y electricidad: en tierra, en el despegue y como respaldo en vuelo."},{"id":"apu-1-c2","title":"A small gas turbine","body":"Su corazón es una **turbina de gas de un solo eje**. Entrega **potencia mecánica** que mueve una caja de accesorios (el generador, el starter y otros), y además **produce el bleed** para arrancar motores y para el sistema neumático.\n\nTiene su **propio sistema de aceite**, independiente, para lubricar y enfriar. El aire entra por una toma con una **flap** eléctrica.","diagram":{"alt":"Esquema del APU: el aire entra por la air intake flap a la turbina de un solo eje; la turbina mueve la caja de accesorios, con el generador y el starter, y produce el bleed; el ECB la controla; el combustible viene de la línea izquierda y el aceite es propio.","src":"assets/estaciones/diagramas/apu-partes.svg"},"keyIdea":"Turbina de un solo eje: potencia mecánica para el generador y bleed; aceite propio."},{"id":"apu-1-c3","title":"The ECB","body":"El **ECB** (Electronic Control Box) es el controlador digital de autoridad completa del APU. Hace casi toda su lógica:\n- ordena y vigila el **arranque**;\n- vigila la velocidad y la temperatura;\n- vigila el bleed;\n- ordena el **apagado** y el apagado automático.\n\nTambién controla el **starter eléctrico** y el **caudal de combustible**.","keyIdea":"El ECB arranca, vigila y apaga el APU; controla el starter y el combustible."},{"id":"apu-1-c4","title":"Power and fuel to start","body":"Para arrancar, el APU puede usar las **baterías**, la **red eléctrica normal** del avión o **energía de tierra**.\n\nEl combustible viene de la **línea izquierda**, con la presión de las bombas de los tanques; si esa presión falta, arranca sola la **APU fuel pump**.","keyIdea":"Arranca con baterías, red normal o tierra; combustible de la línea izquierda."}],"test":[{"id":"apu-1-t1","type":"mcq","question":"THE BASIC ELEMENT OF THE APU IS A SINGLE SHAFT GAS TURBINE WHICH DELIVERS ______ POWER FOR DRIVING THE ACCESSORY GEARBOX (ELECTRICAL GENERATOR) AND PRODUCES BLEED AIR (ENGINE STARTING AND PNEUMATIC SUPPLY).","options":["2ND STAGE COMPRESSOR","3RD STAGE TURBINE","2ND STAGE TURBINE.","MECHANICAL SHAFT"],"correct":3,"explanation":"El APU es una turbina de gas de un solo eje que entrega potencia mecánica de eje (mechanical shaft power) para mover la caja de accesorios y el generador eléctrico, además de producir aire sangrado para arranque de motores y suministro neumático.","taughtIn":["apu-1-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1cd98j7"}},{"id":"apu-1-t2","type":"mcq","question":"THE APU HAS AN INTEGRAL INDEPENDENT LUBRICATION SYSTEM FOR LUBRICATION AND COOLING.","options":["TRUE.","FALSE."],"correct":0,"explanation":"Verdadero: el APU cuenta con su propio sistema de lubricación autocontenido, independiente del sistema de aceite de los motores principales.","taughtIn":["apu-1-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:2qevqp"}},{"id":"apu-1-t3","type":"mcq","question":"THE ELECTRONIC CONTROL BOX (ECB) IS PRIMARILY A FULL AUTHORITY DIGITAL ELECTRONIC CONTROLLER THAT PERFORMS THE APU SYSTEM LOGIC FOR ALL MODES OF APU OPERATION SUCH AS:","options":["SEQUENCE AND MONITORING OF START.","SPEED AND TEMPERATURE MONITORING.","MONITORING OF BLEED AIR AND SHUT DOWN.","ALL OF THE ABOVE."],"correct":3,"explanation":"El ECB abarca toda la lógica del sistema APU: secuenciamiento y monitoreo del arranque, monitoreo de velocidad y temperatura, y supervisión de bleed air y shutdown; todas estas funciones forman parte de su control integral.","taughtIn":["apu-1-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:z09x07"}},{"id":"apu-1-t4","type":"mcq","question":"¿Qué computador controla las secuencias de start y shutdown del APU?","options":["ECB","FADEC","BMC","SFCC"],"correct":0,"explanation":"El Electronic Control Box es el controlador del APU. Gestiona la lógica de start/shutdown y monitoriza parámetros/protecciones propios de la unidad.","taughtIn":["apu-1-c3"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:a5el1u"}},{"id":"apu-1-t5","type":"mcq","question":"THE ECB (ELECTRONIC CONTROL BOX) CONTROLS THE FUEL FLOW.","options":["TRUE.","FALSE."],"correct":0,"explanation":"Verdadero: el ECB también gestiona el flujo/dosificación de combustible del APU, como parte de su rol de controlador digital de autoridad plena para ese sistema.","taughtIn":["apu-1-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1y1my5e"}},{"id":"apu-1-t6","type":"mcq","question":"THE APU MAY OBTAIN POWER FOR STARTING FROM:","options":["GROUND SERVICES.","NORMAL AIRCRAFT SUPPLY.","THE AIRCRAFT'S BATTERIES OR IN COMBINATION WITH THE EXTERNAL POWER.","ALL OF THE ABOVE."],"correct":3,"explanation":"El APU puede recibir energía para su arranque desde servicios de tierra, desde el suministro eléctrico normal del avión, o desde las baterías (solas o en combinación con energía externa); todas estas fuentes son válidas según la situación.","taughtIn":["apu-1-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:119gu6y"}}]},
{"id":"apu-2","subject":"apu","order":2,"kind":"lesson","level":1,"ident":"AST","title":"APU start","goal":"Explicar qué pasa al poner el APU MASTER SW en ON y al presionar START, y cuándo el APU está disponible.","intro":"Dos botones arrancan el APU. Cada uno hace su parte, y en orden.","minutes":6,"cards":[{"id":"apu-2-c1","title":"MASTER SW ON","body":"El **APU MASTER SW** da energía al APU y a sus protecciones, y comanda el arranque y el apagado. Al ponerlo en ON, el APU **todavía no arranca**; se prepara:\n- el ECB recibe energía y hace un **power-up test**;\n- se abre la **air intake flap**;\n- se abre la **APU fuel isolation valve** y, si ninguna bomba de los tanques funciona, opera la APU fuel pump;\n- si el avión tiene energía, aparece la **página APU** en el ECAM.","diagram":{"alt":"La secuencia de arranque del APU en dos pasos. MASTER SW ON: power-up test del ECB, se abre la air intake flap y la fuel isolation valve, y aparece la página APU. START ON, con la flap abierta: starter, ignición, el starter se desconecta a 55 o 60 % de N y la luz AVAIL se enciende al llegar a la velocidad.","src":"assets/estaciones/diagramas/apu-arranque.svg"},"keyIdea":"MASTER SW ON: power-up test, flap abierta, combustible disponible y página APU."},{"id":"apu-2-c2","title":"START ON","body":"Con el **START** en ON (y el MASTER SW ya en ON):\n- cuando la flap está **totalmente abierta**, se energiza el **starter**: con la flap cerrada, el starter no engrana;\n- 1,5 segundos después se enciende la **ignición**;\n- a 55 o 60 % de N (según el avión) se apagan el starter y la ignición;\n- al llegar a la velocidad, la luz ON se apaga y se enciende **AVAIL**: el APU puede dar bleed y electricidad.","keyIdea":"START con la flap abierta: starter, ignición, y AVAIL al llegar a la velocidad."},{"id":"apu-2-c3","title":"When AVAIL comes on","body":"El valor de N para AVAIL **no es el mismo en todos los aviones**:\n- en unos, AVAIL aparece con N **sobre 95 %**;\n- en otros, con N sobre 99,5 %, o 2 segundos después de pasar 95 %.\n\nEl memo verde **APU AVAIL** del ECAM lo muestra también.","keyIdea":"AVAIL: sobre 95 % en unos aviones; sobre 99,5 % o 2 s después de 95 % en otros."},{"id":"apu-2-c4","title":"In the cockpit preparation","body":"En la preparación de la cabina:\n- **APU MASTER SW en ON**, y esperar **al menos 3 segundos** antes del **APU START**;\n- cuando el APU está **AVAIL**: **APU BLEED en ON**.\n\nNo se usa el APU BLEED si el personal de tierra confirma que hay conectada una unidad de aire de tierra (LP o HP).","keyIdea":"MASTER, 3 segundos, START; APU BLEED con AVAIL y sin unidad de aire de tierra."}],"test":[{"id":"apu-2-t1","type":"mcq","question":"WHEN THE APU MASTER SW IS SELECTED ON:","options":["THE APU COMPUTER AUTOMATICALLY COMPLETES A SELF-TEST, OPENS THE AIR INTAKE FLAP AND SUPPLIES FUEL PRESSURE.","THE APU COMPUTER AUTOMATICALLY STARTS THE APU.","CONNECTS THE APU GENERATOR TO THE AIRCRAFT ELECTRICAL SYSTEM.","THE APU DOOR OPENS."],"correct":0,"explanation":"Al seleccionar el APU MASTER SW en ON, el computador del APU ejecuta automáticamente un autotest, abre la air intake flap y suministra presión de combustible; esto es una fase de preparación, distinta de arrancar realmente el APU (que requiere el pushbutton START) o de conectar el generador (que ocurre una vez que el APU está disponible).","taughtIn":["apu-2-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:q1802k"}},{"id":"apu-2-t2","type":"mcq","question":"WHEN SELECTED ON, THE APU START PUSH BUTTON, WILL:","options":["CONNECT THE APU GENERATOR TO THE AIRCRAFT ELECTRICAL SYSTEM.","START THE APU IF THE APU MASTER SW WAS PREVIOUSLY SELECTED ON.","OPEN THE AIR INTAKE FLAP AND SUPPLY FUEL PRESSURE."],"correct":1,"explanation":"El pushbutton de START del APU inicia efectivamente la secuencia de arranque, pero solo si el APU MASTER SW fue seleccionado ON previamente; no es el START el que abre la toma de aire ni conecta el generador por sí mismo, esas son funciones asociadas a otras etapas de la secuencia.","taughtIn":["apu-2-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:8itjmw"}},{"id":"apu-2-t3","type":"mcq","question":"THE STARTER ENGAGES IF THE AIR INTAKE IS CLOSED AND THE MASTER SW AND THE START PUSHBUTTONS ARE ON.","options":["TRUE.","FALSE."],"correct":1,"explanation":"Falso: el motor de arranque no puede engranar con la toma de aire cerrada; la apertura de la air intake flap es un requisito previo (interlock) para que el starter pueda engranar, independientemente de que el master switch y el pushbutton de start estén en ON.","taughtIn":["apu-2-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1dyyyd"}},{"id":"apu-2-t4","type":"mcq","question":"¿Es universal el valor de APU N a partir del cual aparece APU AVAIL en toda la familia A320?","options":["Porque AVAIL depende solo de EGT y no considera N","Porque el criterio de AVAIL varía con la configuración","Porque el criterio depende del peso y del centro de gravedad","Porque el criterio cambia con el modo seleccionado del A/THR"],"correct":1,"explanation":"No: según el avión, AVAIL aparece con N sobre 95 %, o con N sobre 99,5 % (o 2 segundos después de pasar 95 %).","taughtIn":["apu-2-c3"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1a9fji0"}},{"id":"apu-2-t5","type":"mcq","question":"Al iniciar el APU desde el cockpit, ¿qué espera mínima indica el SOP entre APU MASTER SW ON y APU START ON?","options":["No hay espera","Al menos 3 s","30 s","1 min"],"correct":1,"explanation":"El SOP exige esperar al menos 3 s después de APU MASTER SW ON antes de seleccionar APU START ON.","taughtIn":["apu-2-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:16unhbz"}},{"id":"apu-2-t6","type":"mcq","question":"¿Cuándo indica el SOP seleccionar APU BLEED ON durante la secuencia normal?","options":["Inmediatamente al seleccionar MASTER SW","Cuando el APU está AVAIL","Antes de START","Solo después del engine start"],"correct":1,"explanation":"El SOP indica seleccionar APU BLEED ON cuando aparece APU AVAIL. La secuencia publicada no sitúa esa selección antes de AVAIL.","taughtIn":["apu-2-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1ye21e"}}]},
{"id":"apu-3","subject":"apu","order":3,"kind":"lesson","level":1,"ident":"ENG","title":"Engines and FADEC","goal":"Explicar qué motores puede tener el A320, cómo funcionan, qué mueve su caja de accesorios y qué hace el FADEC.","intro":"Pasamos a los motores. Primero, cuáles son, y quién los controla.","minutes":5,"cards":[{"id":"apu-3-c1","title":"Three engine types","body":"Según el avión, el A320 tiene dos motores de uno de estos tipos:\n- **IAE V2500-A5**;\n- **CFM56-5B**;\n- **PW1100G-JM** (Pratt & Whitney), en los A320neo.\n\nTodos son **turbofan de alto bypass**: el fan comprime el aire, la mayor parte pasa por afuera del núcleo y da la mayor parte del empuje, y el resto entra al núcleo, donde se comprime, se quema con combustible y mueve las turbinas.","diagram":{"alt":"Corte simplificado de un turbofan: el fan y el compresor de baja (LP), la mayor parte del aire por afuera del núcleo; en el núcleo, el compresor de alta (HP), la cámara de combustión y las turbinas HP y LP. N1 es la velocidad del fan y N2 la del rotor HP. La caja de accesorios, movida por el eje HP.","src":"assets/estaciones/diagramas/apu-motor.svg"},"keyIdea":"IAE V2500, CFM56-5B o PW1100G (neo); todos turbofan de alto bypass."},{"id":"apu-3-c2","title":"N1, N2 and the gearbox","body":"**N1** es la velocidad del fan y **N2** la del rotor de alta presión, en porcentaje.\n\nLa **caja de accesorios**, movida por el eje de alta presión, mueve: la bomba de aceite, la bomba principal de combustible, las **bombas hidráulicas** (Green y Yellow), los **generadores**, el **alternador del FADEC** y el starter neumático.","keyIdea":"N1 = fan, N2 = rotor HP; la caja de accesorios mueve bombas, generadores y el alternador del FADEC."},{"id":"apu-3-c3","title":"FADEC","body":"Cada motor tiene su **FADEC** (Full Authority Digital Engine Control), que hace el manejo completo del motor:\n- control del combustible y de la aceleración;\n- protección contra los límites (overspeed de N1 y N2, EGT en el arranque);\n- manejo del empuje (palancas y A/THR);\n- arranque automático y manual, reversers y vigilancia.\n\nTiene **dos canales**: uno activo y otro en espera, que toma el control si el primero falla. Se alimenta con su **propio alternador magnético**.","keyIdea":"FADEC: manejo completo del motor, dos canales y su propio alternador."},{"id":"apu-3-c4","title":"Thrust parameter","body":"El FADEC fija el empuje con un parámetro que depende del motor:\n- **IAE V2500:** el **EPR** (Engine Pressure Ratio) es el modo normal; si se pierde, el FADEC pasa a un modo N1;\n- **CFM56 y PW1100G:** el **N1**.","keyIdea":"IAE: EPR. CFM y PW: N1."}],"test":[{"id":"apu-3-t1","type":"mcq","question":"¿Qué tipo de funciones concentra el FADEC del motor?","options":["Indicación y registro de parámetros, sin intervenir en el control del motor","Control del motor, protecciones, power management, start, reverser y monitoring","Ignition y starter durante el arranque, sin funciones durante el resto del vuelo","Autothrust y cálculo de performance, mientras otro sistema gobierna el motor"],"correct":1,"explanation":"FADEC no es simplemente un “control de combustible”. Integra el control del motor, limita condiciones que podrían exceder márgenes, gestiona la potencia solicitada y automatiza/monitoriza fases como el start y el reverser, además de registrar fallas.","taughtIn":["apu-3-c3"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:3b7ff0"}},{"id":"apu-3-t2","type":"mcq","question":"THE FULL AUTHORITY DIGITAL ENGINE CONTROL (FADEC) CONTROLS WHICH OF THE FOLLOWING FUNCTIONS:","options":["FUEL METERING","ENGINE LIMITS","AUTOMATIC AND MANUAL STARTING","ALL OF THE ABOVE"],"correct":3,"explanation":"El FADEC controla de forma integral la dosificación de combustible, los límites del motor, y el arranque tanto automático como manual; todas estas funciones forman parte de su autoridad plena sobre el motor.","taughtIn":["apu-3-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:v8sp62"}},{"id":"apu-3-t3","type":"mcq","question":"THE FADEC IS NORMALLY POWERED BY:","options":["THE RAT.","IT'S OWN MAGNETIC ALTERNATOR.","THE NORMAL AIRCRAFT ELECTRICAL SYSTEM."],"correct":1,"explanation":"El FADEC tiene como fuente interna su propio alternador magnético, que mueve la caja de accesorios del motor.","taughtIn":["apu-3-c2","apu-3-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:17j7vve"}},{"id":"apu-3-t4","type":"mcq","question":"THE NORMAL MODE TO SET THRUST IS:","options":["EPR.","N1.","N2."],"correct":0,"explanation":"Respuesta del examen: EPR. Así es en los motores IAE V2500, donde el EPR es el modo normal. Los CFM56 y los PW1100G fijan el empuje con el N1.","taughtIn":["apu-3-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:v2whyh"}}]},
{"id":"apu-4","subject":"apu","order":4,"kind":"lesson","level":2,"ident":"ASD","title":"APU shutdown","goal":"Explicar el apagado normal del APU, su período de enfriamiento y el apagado de emergencia desde la cabina o desde afuera.","intro":"Apagar el APU no siempre es inmediato. Veamos por qué, y cuándo sí lo es.","minutes":5,"cards":[{"id":"apu-4-c1","title":"Manual shutdown","body":"Al presionar el **APU MASTER SW** (a OFF) empieza el apagado normal:\n- se apagan la luz ON del MASTER SW y AVAIL del START;\n- si el avión **estaba usando el APU bleed**, el APU sigue funcionando un **período de enfriamiento de 60 a 120 segundos** antes de detenerse;\n- a unos **7 %** de N, la air intake flap se cierra.\n\nPor eso, después de apagarlo, la indicación AVAIL puede seguir un rato si se usó el bleed.","diagram":{"alt":"Tres formas de apagar el APU. Manual, con el MASTER SW: si se usó el bleed, sigue 60 a 120 segundos para enfriarse, y la flap se cierra a 7 % de N. Automático, por el ECB ante una falla: sin enfriamiento. De emergencia, con el APU FIRE pb o con el APU SHUT OFF del panel exterior: inmediato, sin enfriamiento.","src":"assets/estaciones/diagramas/apu-apagado.svg"},"keyIdea":"Apagado normal: con bleed en uso, 60 a 120 s de enfriamiento; la flap se cierra a 7 %."},{"id":"apu-4-c2","title":"Emergency shutdown","body":"El apagado de **emergencia** es **inmediato, sin período de enfriamiento**. Ocurre al presionar:\n- el **APU FIRE pb** del overhead, o\n- el **APU SHUT OFF** del panel de energía externa: el APU **se puede apagar desde afuera** del avión.\n\nAparece la alerta APU EMER SHUT DOWN.","keyIdea":"Emergencia: APU FIRE pb o APU SHUT OFF exterior; sin enfriamiento."},{"id":"apu-4-c3","title":"Start attempts","body":"Después de **tres intentos de arranque seguidos**, hay que esperar **60 minutos** antes de intentarlo de nuevo.\n\nDurante la carga de combustible se puede arrancar o apagar el APU, pero si no arrancó o tuvo un apagado automático, no se vuelve a arrancar; si se derrama combustible, se hace un apagado normal.","keyIdea":"Tres arranques seguidos: esperar 60 minutos."}],"test":[{"id":"apu-4-t1","type":"mcq","question":"WHEN THE APU MASTER SWITCH IS RELEASED, A NORMAL APU SHUTDOWN OCCURS:","options":["WITHOUT DELAY IN ALL CASES.","WITHOUT A DELAY, IN ALL CASES.","WITH A DELAY IF THE BLEED AIR WAS IN USE."],"correct":2,"explanation":"Si se estaba usando el APU bleed, el APU sigue funcionando un período de enfriamiento de 60 a 120 segundos antes de detenerse.","taughtIn":["apu-4-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:25oh0m"}},{"id":"apu-4-t2","type":"mcq","question":"YOU SWITCH OFF THE APU BUT CURIOUSLY YOU STILL HAVE THE APU AVAIL INDICATIONS.","options":["THERE IS A FAULT WITH THE APU MASTER SWITCH.","THE APU WILL RUN FOR A COOLING PERIOD OF 60 TO 120 SECONDS BECAUSE YOU HAVE BEEN USING THE APU BLEED.","YOU HAVE TO PUSH THE START SW TO INITIATE THE SHUT DOWN SEQUENCE."],"correct":1,"explanation":"Si se venía usando el bleed del APU, este continúa funcionando durante un período de enfriamiento de 60 a 120 segundos antes de apagarse realmente, por lo que la indicación AVAIL puede persistir brevemente después de seleccionar el master switch OFF.","taughtIn":["apu-4-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:d3dahw"}},{"id":"apu-4-t3","type":"mcq","question":"Durante el manual shutdown, ¿aproximadamente a qué APU N se cierra la air-intake flap?","options":["7 %","25 %","50 %","95 %"],"correct":0,"explanation":"La flap permanece abierta durante gran parte de la deceleración y cierra cerca de N 7 %, cuando ya no se requiere el flujo de admisión normal.","taughtIn":["apu-4-c1"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:j0fk6n"}},{"id":"apu-4-t4","type":"mcq","question":"¿Qué diferencia esencial hay entre manual shutdown y emergency shutdown respecto del cooling period?","options":["Emergency shutdown puede cortar el APU sin esperar el cooling period","Emergency shutdown añade siempre 5 min adicionales de cooling","Ambos shutdown deben respetar obligatoriamente 120 s de cooling","Manual shutdown es inmediato y emergency shutdown espera a N 7 % antes de cortar fuel"],"correct":0,"explanation":"La prioridad de una emergencia es eliminar rápidamente la fuente de riesgo. Por eso un emergency shutdown no espera el periodo térmico previsto en una parada normal.","taughtIn":["apu-4-c1","apu-4-c2"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1fabrg2"}},{"id":"apu-4-t5","type":"mcq","question":"THE APU CANNOT BE SHUT DOWN FROM OUTSIDE THE AIRCRAFT.","options":["TRUE.","FALSE.","APU SHUT OFF PUSHBUTTON ON EXTERNAL POWER PANEL."],"correct":1,"explanation":"Falso: el APU SHUT OFF del panel de energía externa ordena un apagado de emergencia desde afuera del avión.","taughtIn":["apu-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1l2d7j6"}},{"id":"apu-4-t6","type":"mcq","question":"Después de más de tres intentos consecutivos de APU start, ¿qué hay que hacer antes de otro intento?","options":["Esperar 5 min","Esperar 15 min","Esperar 60 min","No existe limitación"],"correct":2,"explanation":"Después de tres intentos de arranque seguidos, hay que esperar 60 minutos antes de un nuevo intento.","taughtIn":["apu-4-c3"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1psxy5z"}}]},
{"id":"apu-5","subject":"apu","order":5,"kind":"lesson","level":2,"ident":"AUT","title":"APU automatic shutdown","goal":"Explicar por qué el ECB apaga solo el APU, algunas de sus causas y qué indica la luz FAULT del MASTER SW.","intro":"El ECB vigila al APU todo el tiempo, y lo apaga solo si algo anda mal.","minutes":5,"cards":[{"id":"apu-5-c1","title":"Why it shuts down","body":"Ante una falla o un mal funcionamiento, el ECB puede **apagar solo el APU, sin período de enfriamiento**, para evitar daños mayores. Aparece la alerta **APU AUTO SHUT DOWN**.","keyIdea":"Apagado automático: sin enfriamiento, para no dañar más el APU."},{"id":"apu-5-c2","title":"Some causes","body":"Algunas causas, en tierra y en vuelo:\n- **EGT** sobre el límite (unos 700 °C);\n- **baja presión de aceite** o alta temperatura de aceite;\n- **underspeed** (N bajo) o falta de aceleración;\n- pérdida de energía DC, flujo de retorno (reverse flow), no flame o arranque lento, entre otras.\n\nOtras solo en tierra con los motores detenidos: el **fuego del APU**, la falla del ECB, el **overspeed** (N sobre 107 %) y la falta de velocidad.","diagram":{"alt":"Tabla de algunas causas de apagado automático del APU. En tierra y en vuelo: EGT sobre el límite, baja presión de aceite, alta temperatura de aceite, underspeed, falta de aceleración, pérdida de energía DC y reverse flow. Solo en tierra con los motores detenidos: fuego del APU, falla del ECB, overspeed sobre 107 % y falta de velocidad.","src":"assets/estaciones/diagramas/apu-auto.svg"},"keyIdea":"EGT alta, baja presión de aceite, underspeed... El fuego lo apaga solo en tierra, motores detenidos."},{"id":"apu-5-c3","title":"MASTER SW FAULT","body":"La luz **FAULT** del APU MASTER SW se enciende cuando:\n- el APU **falló**, o\n- hay un **apagado automático** en curso, o\n- ocurrió un **apagado de emergencia**.","keyIdea":"FAULT: APU fallado, apagado automático o apagado de emergencia."}],"test":[{"id":"apu-5-t1","type":"mcq","question":"¿Por qué puede el APU hacer un automatic shutdown sin cooling period?","options":["Para reducir consumo al terminar","Para proteger el APU ante una falla","Porque siempre omite el cooling","Para descargar el generator antes"],"correct":1,"explanation":"El cooldown protege al APU durante un shutdown normal, pero ante ciertas fallas la prioridad cambia: continuar funcionando puede producir más daño. El ECB puede ordenar una parada inmediata, sacrificando el cooldown para proteger el equipo.","taughtIn":["apu-5-c1"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:h1uf38"}},{"id":"apu-5-t2","type":"mcq","question":"¿Cuál de estas condiciones es una causa de automatic APU shutdown?","options":["High EGT","GEN OFF normal","BLEED OFF selectivo","Flap abierta en vuelo"],"correct":0,"explanation":"High EGT forma parte de las condiciones de automatic shutdown monitorizadas por el ECB.","taughtIn":["apu-5-c2"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1pxo82s"}},{"id":"apu-5-t3","type":"mcq","question":"¿Cuál de estas condiciones también es una causa de automatic APU shutdown?","options":["Low oil pressure","High oil pressure","GEN desconectado","BLEED cerrada"],"correct":0,"explanation":"Low oil pressure forma parte de las condiciones de automatic shutdown monitorizadas por el ECB.","taughtIn":["apu-5-c2"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:x0vzlc"}},{"id":"apu-5-t4","type":"mcq","question":"¿Qué puede hacer el ECB ante una APU underspeed significativa?","options":["Ordenar automatic shutdown","Mantener el APU funcionando y desconectar únicamente el generator","Cerrar solo APU BLEED y continuar a régimen reducido","Intentar automáticamente un nuevo start sin detener la unidad"],"correct":0,"explanation":"Underspeed indica que el APU no mantiene su régimen normal y puede reflejar una falla de combustión/carga. El ECB lo trata como condición de protección.","taughtIn":["apu-5-c2"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:a2o9kb"}},{"id":"apu-5-t5","type":"mcq","question":"¿Qué condiciones puede indicar la luz FAULT del APU MASTER SW?","options":["APU failed, automatic shutdown en curso o emergency shutdown ocurrido","Simplemente que APU BLEED está seleccionado OFF","Que el APU generator no está conectado aunque sus parámetros sean normales","Que la air-intake flap está abierta durante un start normal"],"correct":0,"explanation":"FAULT puede indicar APU failed, automatic shutdown in progress o que ocurrió un emergency shutdown.","taughtIn":["apu-5-c3"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1rkhmic"}},{"id":"apu-5-t6","type":"mcq","question":"THE APU MASTER SW FAULT LIGHT WILL ILLUMINATE:","options":["WHEN APU LOW OIL PRESSURE IS DETECTED.","WHEN AN AUTOMATIC SHUTDOWN OF THE APU OCCURS.","FOR AN APU OVERHEAT OR APU FIRE.","IF THE BATTERIES ARE SELECTED OFF WHILE THE APU IS OPERATING."],"correct":1,"explanation":"La luz FAULT del APU MASTER SW se enciende de forma genérica ante cualquier shutdown automático del APU (por las diversas causas protegidas por el ECB); no está dedicada específicamente a baja presión de aceite, sobrecalentamiento/fuego (que tiene su propia indicación) ni a la selección de baterías OFF.","taughtIn":["apu-5-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1vaaxi"}}]},
{"id":"apu-6","subject":"apu","order":6,"kind":"lesson","level":2,"ident":"ALM","title":"APU limits","goal":"Explicar hasta dónde se puede arrancar el APU y usar su bleed, y sus límites de velocidad y temperatura.","intro":"El APU funciona en casi todo el envelope, pero su bleed tiene techos distintos según para qué se use.","minutes":4,"cards":[{"id":"apu-6-c1","title":"Starting in flight","body":"El APU **se puede arrancar en todo el envelope normal de vuelo** con la energía eléctrica normal del avión.\n\nCon **solo las baterías** (configuración eléctrica de emergencia), el límite para volver a arrancarlo es **25 000 ft**.","diagram":{"alt":"Altitudes del APU, de abajo hacia arriba: bleed para aire acondicionado con dos packs hasta 15 000 ft; bleed para ayudar al arranque de un motor hasta 20 000 ft; bleed con un pack hasta 22 500 ft (20 000 en algunos aviones); arranque con solo baterías hasta 25 000 ft; electricidad y arranque normal en todo el envelope. Nunca bleed del APU para el wing anti-ice.","src":"assets/estaciones/diagramas/apu-envelope.svg"},"keyIdea":"Arranque en todo el envelope; con solo baterías, hasta 25 000 ft."},{"id":"apu-6-c2","title":"APU bleed ceilings","body":"El bleed del APU tiene un techo según su uso:\n- para **ayudar a arrancar un motor**: 20 000 ft;\n- para el aire acondicionado y la presurización **con un pack**: 22 500 ft (20 000 ft en algunos aviones);\n- **con dos packs**: 15 000 ft.\n\nEl bleed del APU **no se usa para el wing anti-ice**: con el wing anti-ice, el APU sirve solo para electricidad.","keyIdea":"20 000 ft para arrancar un motor; 22 500 con un pack; 15 000 con dos; nunca para el wing anti-ice."},{"id":"apu-6-c3","title":"Speed and EGT","body":"- **N máximo:** 107 %.\n- **EGT máxima en el arranque:** 1 090 °C bajo 35 000 ft (1 120 °C sobre 35 000 ft), con valores distintos en algunos aviones.\n- **EGT máxima con el APU funcionando:** 675 °C en la mayoría de las versiones.\n\nEn la página APU, N pasa a ámbar desde 102 % y a rojo desde 107 %.","keyIdea":"N máximo 107 %; la EGT tiene un límite de arranque y otro de funcionamiento."}],"test":[{"id":"apu-6-t1","type":"mcq","question":"THE APU MAY BE STARTED UP TO WHAT ALTITUDE?","options":["THE APU CAN BE STARTED AT ANY ALTITUDE USING NORMAL AIRCRAFT ELECTRICAL POWER.","THE APU CAN BE STARTED UP TO 35,000 FEET USING ONLY THE AIRCRAFT BATTERIES.","THE APU CAN BE STARTED UP TO 30,000 FEET USING ONLY THE AIRCRAFT BATTERIES.","THE APU CAN BE STARTED UP TO 25,000 FEET USING ONLY THE AIRCRAFT BATTERIES."],"correct":0,"explanation":"Con la energía eléctrica normal del avión, el APU se puede arrancar en todo el envelope normal de vuelo; el límite de 25 000 ft es para el arranque con solo baterías.","taughtIn":["apu-6-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1r8jl2o"}},{"id":"apu-6-t2","type":"mcq","question":"WHAT IS THE MAXIMUM ALTITUDE AT WHICH THE APU MAY BE STARTED USING THE BATTERIES ONLY?","options":["15, 000 FT.","20, 000 FT.","25, 000 FT.","39, 000 FT"],"correct":2,"explanation":"Usando únicamente las baterías (sin energía eléctrica normal disponible), el arranque del APU está limitado a 25,000 ft, a diferencia del arranque con energía eléctrica normal, que no tiene límite de altitud.","taughtIn":["apu-6-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1eoj3v1"}},{"id":"apu-6-t3","type":"mcq","question":"CAN THE APU BE USED WITH WING ANTI-ICE ON?","options":["NO.","YES, BUT ONLY FOR ELECTRICAL POWER. THE APU BLEED VALVE SHOULD NOT BE OPENED WHILE USING WING ANTI-ICE.","YES, EXCEPT DURING APPROACH AND GO-AROUND.","YES, BUT THE ALTITUDE OF UTILIZATION IS LIMITED TO 15,000 FT."],"correct":1,"explanation":"Sí, pero solo para electricidad: el bleed del APU no se usa para el wing anti-ice.","taughtIn":["apu-6-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:16tifvz"}}]},
{"id":"apu-7","subject":"apu","order":7,"kind":"lesson","level":2,"ident":"THL","title":"Thrust levers","goal":"Explicar las posiciones de las thrust levers, cómo el FADEC limita el empuje y cómo se hace un despegue FLEX.","intro":"En el A320 las palancas no se mueven solas. Cada posición le dice al FADEC qué límite usar.","minutes":4,"cards":[{"id":"apu-7-c1","title":"Six positions","body":"Las thrust levers recorren un sector dividido en **cuatro segmentos**, con **seis posiciones** marcadas por detents o topes:\n- **TO/GA** (despegue y go-around);\n- **FLX/MCT** (despegue FLEX o máximo continuo);\n- **CL** (climb);\n- **IDLE** (0);\n- **REV IDLE** y **MAX REV** (reversa).\n\nPara la reversa se levanta la palanca de reversa; desde ahí la palanca ya no se queda en IDLE.","diagram":{"alt":"El sector de las thrust levers con sus seis posiciones, de adelante hacia atrás: TO/GA, FLX/MCT, CL, IDLE (0), REV IDLE y MAX REV. Entre CL e IDLE, el rango del A/THR.","src":"assets/estaciones/diagramas/apu-palancas.svg"},"keyIdea":"Seis posiciones: TO/GA, FLX/MCT, CL, IDLE, REV IDLE y MAX REV."},{"id":"apu-7-c2","title":"The FADEC sets the limit","body":"Las palancas **solo se mueven a mano**: con el A/THR activo no se mueven. El FADEC lee la posición y calcula el **límite de empuje** de esa posición; entre dos detents usa el del **detent más alto**.\n\nEn manual, el empuje lo da la posición de la palanca. Con el **A/THR** activo, el empuje lo calcula el FMGC, limitado al valor de la posición de la palanca (salvo con alpha floor).","keyIdea":"Palancas solo a mano; el FADEC limita el empuje según la posición."},{"id":"apu-7-c3","title":"FLEX takeoff","body":"El **FLEX** es un empuje **reducido para el despegue**. Para tenerlo, la tripulación ingresa una **temperatura FLEX en la página PERF TAKEOFF** del MCDU y pone las palancas en **FLX/MCT**:\n- si la temperatura FLEX es mayor que la OAT, el motor da empuje FLEX;\n- si no, da MCT.\n\nEn cualquier momento, TO/GA da el empuje máximo. Después del despegue, para pasar de FLX a MCT se lleva la palanca a TO/GA o CL y de vuelta a FLX/MCT.","keyIdea":"FLEX: temperatura en PERF TAKEOFF y palancas en FLX/MCT; TO/GA siempre da el máximo."}],"test":[{"id":"apu-7-t1","type":"mcq","question":"HOW MANY THRUST LEVER POSITIONS ARE THERE, AND HOW ARE THEY LABELLED?","options":["SIX, TO/GA, MCT, FLEX, CL, IDLE AND REV IDLE.","SIX, TO/GA, FLX/MCT, CL, IDLE, REV IDLE AND MREV.","FOUR, TO/GA, FLX/MCT, CL, IDLE.","FIVE, TO/GA, FLX/MCT, CT, IDLE AND REV IDLE."],"correct":1,"explanation":"La palanca de empuje del A320 tiene seis posiciones/detentes: TO/GA, FLX/MCT, CL, IDLE, REV IDLE y MREV (máxima reversa), cubriendo desde el máximo empuje de despegue hasta la máxima reversa disponible.","taughtIn":["apu-7-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1yz6ly5"}},{"id":"apu-7-t2","type":"mcq","question":"WHEN THE A/THR SYSTEM IS IN USE:","options":["THE THROTTLES MOVE AUTOMATICALLY ACCORDING TO FADEC COMMANDS.","THE THROTTLES CAN ONLY BE MOVED MANUALLY.","THE THROTTLES WILL MOVE WHEN THE A/THR P/B IS USED."],"correct":1,"explanation":"Las thrust levers solo se mueven a mano: con el A/THR activo quedan donde las dejó la tripulación, y el empuje se limita al valor de su posición.","taughtIn":["apu-7-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1rma18p"}},{"id":"apu-7-t3","type":"mcq","question":"WHAT DOES THE FLEX REPRESENT IN THE FLX/MCT DETENT?","options":["THIS IS A REDUCED THRUST SETTING USED FOR TAKEOFF.","THIS IS THE THRUST SETTING THAT SHOULD BE CHOSEN IN THE CASE OF A SINGLE- ENGINE GO-AROUND.","NONE OF THE ABOVE."],"correct":0,"explanation":"FLEX es un ajuste de empuje reducido usado específicamente para el despegue (mediante temperatura asumida), no la referencia que corresponde usar en un go-around con un motor inoperativo, que corresponde a MCT en ese mismo detente.","taughtIn":["apu-7-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:16m9t8s"}},{"id":"apu-7-t4","type":"mcq","question":"WHAT IS REQUIRED FOR THE FADEC TO COMPUTE A REDUCED THRUST SETTING?","options":["A FLEX TEMPERATURE MUST BE ENTERED ON THE INIT PAGE OF THE MCDU.","NOTHING, IT IS AN AUTOMATIC FUNCTION OF THE FADEC.","A FLEX TEMPERATURE MUST BE ENTERED ON THE TAKE OFF PERF PAGE OF THE MCDU.","A OR C ARE CORRECT."],"correct":2,"explanation":"Para que el FADEC calcule un ajuste de empuje reducido (FLEX), la tripulación debe ingresar la temperatura FLEX en la página TAKE OFF PERF del MCDU, no en la página INIT, y no es un cálculo automático sin ese dato.","taughtIn":["apu-7-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:m6z5wl"}}]},
{"id":"apu-8","subject":"apu","order":8,"kind":"lesson","level":2,"ident":"AUS","title":"Automatic engine start","goal":"Explicar la secuencia del arranque automático, qué controla el FADEC y qué hace si el arranque falla en tierra.","intro":"En el A320, el arranque normal lo hace el FADEC. La tripulación pone dos controles y vigila.","minutes":6,"cards":[{"id":"apu-8-c1","title":"Step 1: ENG MODE IGN","body":"Con el **ENG MODE** en **IGN/START**:\n- aparece la página ENG en el ECAM;\n- se **cierran las pack valves**.\n\nSi en 30 segundos no se pone un ENG MASTER en ON, las pack valves se abren de nuevo.","diagram":{"alt":"Arranque automático en tres pasos. Uno: ENG MODE en IGN/START, aparece la página ENG y se cierran las pack valves. Dos: ENG MASTER en ON, se abren la LP fuel valve y la start valve, después la ignición y la HP fuel valve; cuando N2 llega a 43, 50 o 55 % según el motor, se cierra la start valve y se apaga la ignición. Tres: ENG MODE en NORM.","src":"assets/estaciones/diagramas/apu-arranque-motor.svg"},"keyIdea":"ENG MODE en IGN: página ENG y pack valves cerradas."},{"id":"apu-8-c2","title":"Step 2: ENG MASTER ON","body":"Con el **ENG MASTER** en ON, el FADEC tiene la **autoridad completa** del arranque. Controla la **start valve**, la **ignición**, la **HP fuel valve** y el caudal de combustible, y vigila N1, N2, el fuel flow y la EGT:\n- se abren la LP fuel valve y la start valve (el starter gira el motor con aire);\n- después se encienden la ignición y la HP fuel valve;\n- cuando N2 llega a unos 43, 50 o 55 % según el motor, se cierra la start valve y se apaga la ignición.\n\nAl final, el ENG MODE vuelve a NORM.","keyIdea":"ENG MASTER ON: el FADEC abre la start valve, enciende y da combustible, y corta al llegar a N2."},{"id":"apu-8-c3","title":"Abort and dry crank","body":"Si el arranque falla **en tierra**, el FADEC lo **aborta solo**: cierra la HP fuel valve y la start valve, apaga la ignición y hace un **dry crank** (gira el motor sin combustible) para sacar los vapores de combustible. Esto ocurre mientras el ENG MASTER sigue en ON; según el motor, el FADEC también maneja los intentos siguientes.\n\nSi el ECAM lo pide, la tripulación interrumpe el arranque con el ENG MASTER en OFF.","keyIdea":"En tierra el FADEC aborta solo y hace un dry crank; el ENG MASTER OFF interrumpe."},{"id":"apu-8-c4","title":"Start faults","body":"El FADEC detecta fallas del arranque y las muestra con **ENG START FAULT** en el ECAM. Según el motor, entre otras:\n- **no light up:** no hay encendido;\n- **hung start:** el motor deja de acelerar antes del idle;\n- **overtemperature (hot start):** la EGT pasa el límite;\n- **no N1 rotation:** el fan no gira;\n- **starter time exceeded:** el starter funciona más del tiempo permitido;\n- **thrust lever not at idle;**\n- **starter shaft shear** (PW1100G): se corta el eje del starter.","keyIdea":"START FAULT: no light up, hung start, overtemperature, no N1, starter time, palanca fuera de IDLE."}],"test":[{"id":"apu-8-t1","type":"mcq","question":"Durante un automatic engine start, ¿qué elementos controla y monitoriza el FADEC?","options":["Starter y ignition únicamente, mientras la tripulación controla fuel y start valve","Start valve, HP fuel valve, fuel flow e ignition; además vigila parámetros de start","Starter, bleed valve y packs; los parámetros de motor quedan fuera de su control","N1 y N2 solamente; las válvulas de aire y combustible funcionan de forma independiente"],"correct":1,"explanation":"La automatización del start existe porque el FADEC coordina la apertura/cierre de los elementos de aire, combustible e ignition y vigila N1/N2, fuel flow y EGT. Así puede detectar una secuencia anormal y, en tierra, iniciar abort/recycle cuando corresponde.","taughtIn":["apu-8-c2"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1ck75j2"}},{"id":"apu-8-t2","type":"mcq","question":"THE FADEC WILL AUTOMATICALLY ABORT AN ABNORMAL START THEREBY PROVIDING ENGINE LIMIT PROTECTION, BUT WILL THE FADEC ALSO AUTOMATICALLY DRY CRANK THE ENGINE?","options":["NO, THAT IS WHY THERE IS A CRANK SELECTION ON THE ENG MODE SELECTOR.","YES, EVEN IF THE CREW INTERRUPTS THE START BY PLACING THE ENG MASTER SWITCH TO OFF.","YES, AL LONG AS THE ENG MASTER SWITCH REMAINS IN THE ON POSITION.","NONE OF THE ABOVE."],"correct":2,"explanation":"Sí: tras abortar un arranque anormal, el FADEC inicia automáticamente un ciclo de dry crank para purgar el motor, siempre que el ENG MASTER switch permanezca en ON; si la tripulación lo lleva a OFF, esa secuencia automática se interrumpe.","taughtIn":["apu-8-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:3fia2v"}},{"id":"apu-8-t3","type":"mcq","question":"Durante automatic engine start, si después de introducir fuel e ignition no aparece el aumento de temperatura esperado, ¿qué anomalía identifica el FADEC?","options":["No light-up","Hung start","No N1","Starter time exceed"],"correct":0,"explanation":"La ausencia de light-up después de introducir fuel e ignition se identifica como NO LIGHT-UP.","taughtIn":["apu-8-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1j631h5"}},{"id":"apu-8-t4","type":"mcq","question":"Durante automatic engine start, si la temperatura excede el límite previsto, ¿qué anomalía identifica el FADEC?","options":["Hot start / overtemperature","Thrust lever not at IDLE","Starter time exceed","Starter shaft shear"],"correct":0,"explanation":"Una temperatura excesiva durante el start corresponde a HOT START / OVERTEMPERATURE.","taughtIn":["apu-8-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:139r4uw"}},{"id":"apu-8-t5","type":"mcq","question":"En la alerta ENG 1(2) START FAULT, si el fan no muestra la respuesta esperada durante el arranque, ¿qué condición de fallo se indica?","options":["No N1 rotation","Hung start","No light-up","Starter time exceed"],"correct":0,"explanation":"En la versión de la alerta ENG 1(2) START FAULT aplicable a ciertos MSN, el arranque fallido puede deberse a: no light up, engine stall, engine overtemperature, hung start, no N1 rotation, starter time exceeded, thrust lever not at idle, hot start o starter shaft shear. Si el fan no responde como se espera (no gira), la condición es No N1 rotation.","taughtIn":["apu-8-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1on2nq1"}},{"id":"apu-8-t6","type":"mcq","question":"Durante automatic engine start, ¿qué posición anormal de las thrust levers monitoriza el FADEC?","options":["Thrust lever not at IDLE","Hot start / overtemperature","Starter time exceed","Starter shaft shear"],"correct":0,"explanation":"Durante automatic start, el FADEC monitoriza la condición THRUST LEVER NOT AT IDLE.","taughtIn":["apu-8-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1ylhzi8"}}]},
{"id":"apu-9","subject":"apu","order":9,"kind":"lesson","level":3,"ident":"MST","title":"Manual start and ignition","goal":"Explicar cómo se hace un arranque manual, qué cambia en el control del FADEC, qué igniters se usan y cuándo hay ignición continua.","intro":"Si el arranque automático no resulta, queda el manual. Ahí la tripulación vigila más.","minutes":4,"cards":[{"id":"apu-9-c1","title":"Manual start","body":"Para un arranque manual: **ENG MODE en IGN/START**, **ENG MAN START en ON** (se abre la start valve) y después **ENG MASTER en ON** (el FADEC abre la HP fuel valve y enciende **los dos igniters**). Al llegar a N2 (43, 50 o 55 % según el motor), se cierra la start valve y se corta la ignición.\n\nEl FADEC hace una **vigilancia pasiva**: si el arranque es anormal, avisa en el ECAM, pero **no lo aborta solo**; lo interrumpe la tripulación. En los CFM56 hay una excepción en tierra: el FADEC aborta si se pasa el límite de EGT antes de 50 % de N2.","keyIdea":"Manual: IGN, MAN START y MASTER; dos igniters; el FADEC avisa pero no aborta."},{"id":"apu-9-c2","title":"Igniters","body":"Cada motor tiene **dos igniters** con circuitos independientes, manejados por los canales del FADEC.\n- **Arranque automático en tierra:** el primer intento usa **un igniter**, y el FADEC los alterna en los intentos siguientes.\n- **Arranque manual o en vuelo:** **los dos igniters**.","keyIdea":"Automático en tierra: un igniter, alternando. Manual o en vuelo: los dos."},{"id":"apu-9-c3","title":"Continuous ignition","body":"La **ignición continua** mantiene la combustión. Se pone **a mano** en vuelo con el ENG MODE en IGN/START y el motor funcionando, y el FADEC la pone **sola** en ciertas condiciones, que dependen del motor. En los **IAE V2500**, por ejemplo, con el motor funcionando y:\n- el anti-ice del motor en ON;\n- empuje de despegue TO o FLEX seleccionado;\n- approach idle, entre otras.\n\nEn los CFM56, la pone sola ante un flame out o una falla del EIU, entre otras.","keyIdea":"Continua: a mano con IGN en vuelo; sola en condiciones que dependen del motor."}],"test":[{"id":"apu-9-t1","type":"mcq","question":"THE FADEC HAS CONTROL DURING A MANUAL ENGINE START SEQUENCE EXCEPT FOR:","options":["THE HIGH PRESSURE FUEL VALVE.","THE START VALVE.","AN AUTOMATIC ABORT."],"correct":2,"explanation":"En el arranque manual el FADEC sigue manejando la start valve, la HP fuel valve y la ignición, pero solo vigila: no aborta el arranque por su cuenta. En los CFM56, en tierra, aborta solo si se pasa el límite de EGT antes de 50 % de N2.","taughtIn":["apu-9-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:13nbpw3"}},{"id":"apu-9-t2","type":"mcq","question":"WHICH IGNITION SYSTEMS ARE USED DURING A MANUAL START?","options":["A.","B.","BOTH A AND B."],"correct":2,"explanation":"En un arranque manual se usan los dos igniters (A y B). En el arranque automático en tierra, el primer intento usa uno y el FADEC los alterna.","taughtIn":["apu-9-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:fa997x"}},{"id":"apu-9-t3","type":"mcq","question":"CONTINUOUS IGNITION IS AUTOMATICALLY PROVIDED DURING THE FOLLOWING:","options":["FLEX OR TO/GA THRUST IS SELECTED ON THE GROUND.","ENG ANTICE SWITCH IS ON.","ENGINE APPROACH IDLE SELECTED.","ALL OF THE ABOVE."],"correct":3,"explanation":"Respuesta del examen: todas. Es la lógica de los motores IAE V2500: con el motor funcionando, el FADEC pone la ignición continua con el anti-ice del motor en ON, con empuje de despegue TO o FLEX y en approach idle, entre otras. Los CFM56 tienen otra lista.","taughtIn":["apu-9-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:27ywg4"}}]},
{"id":"apu-repaso","subject":"apu","order":10,"kind":"review","level":3,"ident":"RAP","title":"APU and powerplant review","goal":"Repasar el APU y los motores: arranque, apagado, límites, FADEC, palancas y arranque de los motores.","intro":"Llegamos al repaso: preguntas de todas las estaciones de APU y powerplant, incluidas algunas nuevas.","minutes":5,"cards":[{"id":"apu-repaso-c1","title":"APU in one page","body":"- **Qué es:** turbina de un solo eje, con aceite propio; da bleed y electricidad; la controla el ECB.\n- **Arranque:** MASTER SW (power-up test, flap, combustible y página APU), 3 segundos, START; AVAIL con N sobre 95 % (o 99,5 % en algunos aviones); APU BLEED con AVAIL y sin unidad de aire de tierra.\n- **Apagado:** con bleed en uso, 60 a 120 s de enfriamiento; automático o de emergencia, sin enfriamiento; APU SHUT OFF desde afuera.\n- **Límites:** arranque en todo el envelope; con baterías hasta 25 000 ft; bleed nunca para el wing anti-ice.","keyIdea":"ECB, MASTER y START, enfriamiento con bleed, 25 000 ft con baterías."},{"id":"apu-repaso-c2","title":"Engines in one page","body":"- **Motores:** IAE V2500, CFM56-5B o PW1100G (neo); FADEC con dos canales y alternador propio.\n- **Empuje:** EPR en los IAE, N1 en los CFM y PW; seis posiciones de palanca; palancas solo a mano; FLEX con temperatura en PERF TAKEOFF.\n- **Arranque automático:** IGN, MASTER ON; el FADEC controla y aborta en tierra.\n- **Arranque manual:** dos igniters; el FADEC avisa pero no aborta.","keyIdea":"Tres motores, FADEC, seis posiciones, arranque automático y manual."}],"test":[{"id":"apu-repaso-t1","type":"mcq","question":"Al seleccionar APU MASTER SW ON con el APU parado, ¿qué ocurre primero en la secuencia lógica?","options":["Se energiza el sistema y el ECB realiza un power-up test","La APU generator se conecta inmediatamente a ambos AC BUS","La bleed valve abre antes de que se mueva la air-intake flap","El starter queda engranado incluso si la air-intake flap permanece cerrada"],"correct":0,"explanation":"MASTER ON inicia la preparación del APU antes del comando START: se alimenta el sistema y el ECB ejecuta su comprobación de power-up.","taughtIn":["apu-repaso-c1","apu-2-c1"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1kgmxq9"}},{"id":"apu-repaso-t2","type":"mcq","question":"¿Qué precaución indica el SOP respecto de APU BLEED y una ground air unit?","options":["Usar ambos simultáneamente sin restricción","No usar APU BLEED con una LP/HP ground air unit conectada","Usar APU BLEED solo con unidades de alta presión conectadas","El estado de la ground unit no afecta la selección normal"],"correct":1,"explanation":"No se usa el APU BLEED si el personal de tierra confirma que hay conectada una unidad de aire de tierra, de baja (LP) o alta (HP) presión.","taughtIn":["apu-repaso-c1","apu-2-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1hca4im"}},{"id":"apu-repaso-t3","type":"mcq","question":"Si la aeronave está powered durante el arranque del APU, ¿qué presentación aparece automáticamente?","options":["APU page en ECAM","HYD page en el ND","FUEL page en el PFD","STATUS page en ECAM"],"correct":0,"explanation":"La presentación automática facilita monitorizar N, EGT y estado de la unidad durante una fase transitoria importante.","taughtIn":["apu-repaso-c1","apu-2-c1"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:sgz5e6"}},{"id":"apu-repaso-t4","type":"mcq","question":"En un manual shutdown después de haber usado APU bleed, ¿qué puede hacer el APU antes de detenerse?","options":["Mantenerse funcionando durante un cooling period de 60 a 120 s","Apagarse siempre instantáneamente sin ninguna excepción","Aumentar N a 105 % durante exactamente 30 s","Mantener APU generator conectado durante 10 min aunque MASTER esté OFF"],"correct":0,"explanation":"Si se usó el APU bleed, el APU sigue funcionando un período de enfriamiento de 60 a 120 segundos antes de detenerse.","taughtIn":["apu-repaso-c1","apu-4-c1"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:14yzil2"}},{"id":"apu-repaso-t5","type":"mcq","question":"¿Qué control exterior permite ordenar un emergency shutdown del APU desde tierra?","options":["APU SHUT OFF del panel exterior","APU FIRE light del panel exterior","EXT PWR pushbutton del panel exterior","APU BLEED pushbutton del overhead"],"correct":0,"explanation":"El APU SHUT OFF del panel exterior permite ordenar un emergency shutdown desde tierra.","taughtIn":["apu-repaso-c1","apu-4-c2"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:gyuo9b"}},{"id":"apu-repaso-t6","type":"mcq","question":"Durante automatic engine start, si la aceleración se estabiliza a un régimen demasiado bajo y no progresa hacia idle, ¿qué anomalía identifica el FADEC?","options":["Hung start","No light-up","No N1","Starter time exceed"],"correct":0,"explanation":"Una aceleración que se estanca antes de alcanzar el régimen normal de idle corresponde a un HUNG START.","taughtIn":["apu-repaso-c2","apu-8-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1l9aor2"}},{"id":"apu-repaso-t7","type":"mcq","question":"Durante automatic engine start, si el starter permanece actuando más tiempo del permitido, ¿qué anomalía monitoriza el FADEC?","options":["Starter time exceed","Starter shaft shear","Thrust lever not at IDLE","Hot start / overtemperature"],"correct":0,"explanation":"El FADEC monitoriza STARTER TIME EXCEED cuando el starter permanece actuando más tiempo del permitido.","taughtIn":["apu-repaso-c2","apu-8-c4"],"source":{"bank":"fcom","system":"apu_powerplant","appId":"apu_powerplant:1l0h9ps"}}]}
]};
